function ActivityFishPoolContestNode:JumpButtonOnClickHandler()
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id233)
    if not isUnlock then
        local desc = GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id233)
        if not string.isEmpty(desc) then
