        return
    end
    KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID, self._activityDojo.id)
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIFishPoolMainDialog },
            { { id = Constants.UITypeIds.UIActivityMainDialog } }
    )
end
